'use client';

import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import type { AutoplayStep } from '@/registry/ndeko/hooks/use-autoplay';
import {
  hold,
  PRESS_LEAD_MS,
  pressedQuietOf,
  spokenUnless,
  usePress,
} from '@/registry/ndeko/lib/demonstration';
import {
  MinusIcon,
  TrendingDownIcon,
  TrendingUpIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { Skeleton } from '@/registry/ndeko/ui/skeleton';

import { ChartCard } from './_parts/chart-card';
import { DataTable, type DataRow } from './_parts/data-table';
import { walkSteps, whileDemonstrating } from './_parts/demo';
import {
  changeWordsOf,
  COUNT_FORMAT,
  formatCount,
  formatShare,
  formatSigned,
  percentChangeOf,
} from './_parts/format';
import { percentOf, sumOf } from './_parts/scale';
import { StreamedWords } from './_parts/streamed-words';
import { useChartDemo } from './_parts/use-chart-demo';
import {
  arrivedStreamOf,
  spokenStreamOf,
  textOf,
  useWordStream,
  wordsOf,
  type WordStream,
} from './_parts/use-word-stream';

export type MetricDriver = {
  id: string;
  name: string;
  /** How much of the change this driver accounts for, in the unit of the figure. Below zero when it pulled the figure down. */
  contribution: number;
};

export type MetricExplainerProps = {
  title: string;
  /** A short mark beside the title, such as "Illustrative" over sample data. */
  note?: string;
  value: number;
  previous: number;
  /** What the figure counts, in the plural: "teams". */
  unit: string;
  /** What the figure is compared with: "last week". */
  reference: string;
  drivers: readonly MetricDriver[];
  /** The reading of the change, as it arrives from the model. */
  explanation: WordStream;
  /** Explain, then Regenerate once a reading is there. */
  onExplain: () => void;
  /** Lights a driver from outside, for a demonstration or a control beside the piece. */
  spotlightId?: string | null;
  /** Shows the button held down, for a demonstration that presses it. */
  isExplainPressed?: boolean;
  className?: string;
};

type Ranked = {
  driver: MetricDriver;
  /** Its part of everything that moved, gains and losses alike, from 0 to 1. */
  share: number;
};

type Reach = {
  /** The largest gain and the largest loss, both as positive sizes. */
  gain: number;
  loss: number;
};

type Trend = 'up' | 'down' | 'level';

const TREND_ICON: Record<Trend, Icon> = {
  up: TrendingUpIcon,
  down: TrendingDownIcon,
  level: MinusIcon,
};

function trendOf(difference: number): Trend {
  if (difference > 0) {
    return 'up';
  }
  if (difference < 0) {
    return 'down';
  }
  return 'level';
}

function sizeOf(driver: MetricDriver) {
  return Math.abs(driver.contribution);
}

/** Drivers in the order of how much each one counted, whichever way it pushed. */
function rankedOf(drivers: readonly MetricDriver[]): Ranked[] {
  const sizes = drivers.map((driver) => sizeOf(driver));
  const total = sumOf(sizes);
  const moved = Math.max(total, 1);
  const ranked = drivers.map((driver) => {
    const share = sizeOf(driver) / moved;
    return { driver, share };
  });
  return ranked.sort((first, second) => second.share - first.share);
}

function reachOf(drivers: readonly MetricDriver[]): Reach {
  let gain = 0;
  let loss = 0;
  for (const driver of drivers) {
    gain = Math.max(gain, driver.contribution);
    loss = Math.max(loss, -driver.contribution);
  }
  return { gain, loss };
}

function totalsOf(drivers: readonly MetricDriver[]) {
  let gains = 0;
  let losses = 0;
  for (const driver of drivers) {
    gains += Math.max(driver.contribution, 0);
    losses += Math.min(driver.contribution, 0);
  }
  return { gains, losses };
}

/** Where zero sits between the largest loss on the left and the largest gain on the right. */
function zeroShareOf(reach: Reach) {
  const span = reach.gain + reach.loss;
  if (span === 0) {
    return 0;
  }
  return reach.loss / span;
}

function isGain(driver: MetricDriver) {
  return driver.contribution >= 0;
}

function toneOf(driver: MetricDriver) {
  if (isGain(driver)) {
    return 'bg-primary';
  }
  return 'bg-destructive';
}

/** How much of its side a bar leaves empty, as a percentage the fill is slid by. */
function hiddenPercentOf(driver: MetricDriver, reach: Reach) {
  const limit = sideLimitOf(driver, reach);
  if (limit === 0) {
    return 100;
  }
  const filled = sizeOf(driver) / limit;
  const hidden = 1 - filled;
  return hidden * 100;
}

function sideLimitOf(driver: MetricDriver, reach: Reach) {
  if (isGain(driver)) {
    return reach.gain;
  }
  return reach.loss;
}

const SLIDE = 'transition-transform duration-300 ease-(--ease-out-strong)';

type ContributionBarProps = {
  driver: MetricDriver;
  reach: Reach;
};

/**
 * A bar that leaves from zero: to the right for a gain, to the left for a loss. The fill slides out
 * of a slot that clips it, so its rounded end never stretches.
 */
function ContributionBar({ driver, reach }: ContributionBarProps) {
  const zeroShare = zeroShareOf(reach);
  const zero = percentOf(zeroShare);
  const hidden = hiddenPercentOf(driver, reach);
  const gains = isGain(driver);

  return (
    <span aria-hidden='true' className='relative block h-3'>
      {gains && (
        <span
          className='absolute inset-y-0 right-0 overflow-hidden'
          style={{ left: zero }}
        >
          <span
            className={cn('bg-primary absolute inset-0 rounded-e-[4px]', SLIDE)}
            style={{ transform: `translateX(-${hidden}%)` }}
          />
        </span>
      )}
      {!gains && (
        <span
          className='absolute inset-y-0 left-0 overflow-hidden'
          style={{ width: zero }}
        >
          <span
            className={cn(
              'bg-destructive absolute inset-0 rounded-s-[4px]',
              SLIDE
            )}
            style={{ transform: `translateX(${hidden}%)` }}
          />
        </span>
      )}
      <span
        className='hairline-l border-foreground/25 absolute -inset-y-1'
        style={{ left: zero }}
      />
    </span>
  );
}

function litRowOf(isLit: boolean) {
  if (isLit) {
    return 'bg-foreground/[0.03]';
  }
  return undefined;
}

type DriverRowProps = {
  ranked: Ranked;
  reach: Reach;
  isPinned: boolean;
  /** Its part of the total is the one lit now, whoever pointed at it. */
  isLit: boolean;
  onPreview: (id: string | null) => void;
  onTogglePin: (id: string) => void;
};

function DriverRow({
  ranked,
  reach,
  isPinned,
  isLit,
  onPreview,
  onTogglePin,
}: DriverRowProps) {
  const { driver, share } = ranked;

  function preview() {
    onPreview(driver.id);
  }

  function clearPreview() {
    onPreview(null);
  }

  return (
    <button
      type='button'
      aria-pressed={isPinned}
      onPointerEnter={preview}
      onPointerLeave={clearPreview}
      onFocus={preview}
      onBlur={clearPreview}
      onClick={() => onTogglePin(driver.id)}
      className={cn(
        'hover:bg-foreground/[0.03] focus-visible:ring-ring/25 aria-pressed:bg-foreground/[0.05] grid w-full cursor-pointer grid-cols-[minmax(0,1fr)_auto] items-center gap-x-3 gap-y-1 rounded-md px-2 py-1.5 text-start text-[13px] transition-colors duration-150 outline-none focus-visible:ring-[3px]',
        '@sm:h-8 @sm:grid-cols-[minmax(0,6.5rem)_minmax(0,1fr)_auto] @sm:py-0',
        litRowOf(isLit)
      )}
    >
      <span className='col-start-1 row-start-1 truncate'>{driver.name}</span>
      <span className='col-span-2 row-start-2 @sm:col-span-1 @sm:col-start-2 @sm:row-start-1'>
        <ContributionBar driver={driver} reach={reach} />
      </span>
      <span className='col-start-2 row-start-1 flex items-baseline gap-2 tabular-nums @sm:col-start-3'>
        <span className='w-9 text-end font-medium'>
          {formatSigned(driver.contribution)}
        </span>
        <span className='text-muted-foreground w-8 text-end text-xs'>
          {formatShare(share)}
        </span>
      </span>
    </button>
  );
}

function dimmedOf(isDimmed: boolean) {
  if (isDimmed) {
    return 'opacity-30';
  }
  return undefined;
}

/** Gains first, then losses, so the bar reads as what was added and what was taken away. */
function gainsFirst(ranked: readonly Ranked[]) {
  const gains = ranked.filter((entry) => isGain(entry.driver));
  const losses = ranked.filter((entry) => !isGain(entry.driver));
  return [...gains, ...losses];
}

type TotalBarProps = {
  ranked: readonly Ranked[];
  activeId: string | null;
};

/** Everything that moved as one bar, each driver a segment as wide as its share. */
function TotalBar({ ranked, activeId }: TotalBarProps) {
  const segments = gainsFirst(ranked);
  const hasActive = activeId !== null;

  return (
    <span aria-hidden='true' className='flex h-2.5 gap-0.5'>
      {segments.map((entry) => {
        const isDimmed = hasActive && entry.driver.id !== activeId;

        return (
          <span
            key={entry.driver.id}
            className={cn(
              'min-w-0.5 basis-0 rounded-[2px] transition-opacity duration-150',
              toneOf(entry.driver),
              dimmedOf(isDimmed)
            )}
            style={{ flexGrow: entry.share }}
          />
        );
      })}
    </span>
  );
}

const EXPLAIN_LABELS: Record<MorphState, string> = {
  idle: 'Explain',
  busy: 'Reading',
  done: 'Read',
};

const REGENERATE_LABELS: Record<MorphState, string> = {
  idle: 'Regenerate',
  busy: 'Reading',
  done: 'Read',
};

function labelsOf(explanation: WordStream) {
  if (explanation.words.length === 0) {
    return EXPLAIN_LABELS;
  }
  return REGENERATE_LABELS;
}

function buttonStateOf(explanation: WordStream): MorphState {
  const isThinking = explanation.status === 'thinking';
  const isStreaming = explanation.status === 'streaming';
  if (isThinking || isStreaming) {
    return 'busy';
  }
  return 'idle';
}

type WhyItMovedProps = {
  explanation: WordStream;
  onExplain: () => void;
  isExplainPressed: boolean;
};

function WhyItMoved({
  explanation,
  onExplain,
  isExplainPressed,
}: WhyItMovedProps) {
  const isIdle = explanation.status === 'idle';
  const isThinking = explanation.status === 'thinking';
  const isStreaming = explanation.status === 'streaming';
  const hasWords = !isIdle && !isThinking;
  const hasText = explanation.words.length > 0;

  return (
    <div className='bg-foreground/[0.04] flex flex-col gap-2 rounded-lg p-3'>
      <div className='flex items-center justify-between gap-2'>
        <h4 className='text-xs font-medium'>Why it moved</h4>
        <MorphButton
          type='button'
          size='sm'
          variant='outline'
          state={buttonStateOf(explanation)}
          labels={labelsOf(explanation)}
          onClick={onExplain}
          className={pressedQuietOf(isExplainPressed)}
        />
      </div>
      <div className='grid min-h-[3.75rem] text-[13px] leading-5 text-pretty'>
        {isIdle && (
          <p className='text-muted-foreground'>
            Ask for a reading of what moved this figure
          </p>
        )}
        {hasText && (
          <p aria-hidden='true' className='invisible col-start-1 row-start-1'>
            {textOf(explanation)}
          </p>
        )}
        {isThinking && (
          <div className='col-start-1 row-start-1 flex flex-col gap-2 pt-1'>
            <Skeleton className='h-3 w-full' />
            <Skeleton className='h-3 w-4/5' />
          </div>
        )}
        {hasWords && (
          <p className='col-start-1 row-start-1'>
            <StreamedWords
              words={explanation.words}
              shown={explanation.shown}
              isStreaming={isStreaming}
            />
          </p>
        )}
      </div>
    </div>
  );
}

/** What a person points at comes first, then what they pinned, then what was lit from outside. */
function activeIdOf(
  preview: string | null,
  pinned: string | null,
  spotlight: string | null
) {
  return preview ?? pinned ?? spotlight;
}

function captionOf(
  active: Ranked | undefined,
  drivers: readonly MetricDriver[],
  unit: string
) {
  if (active) {
    const amount = formatSigned(active.driver.contribution);
    const share = formatShare(active.share);
    return `${active.driver.name}: ${amount} ${unit}, ${share} of what moved`;
  }
  const totals = totalsOf(drivers);
  const gains = formatSigned(totals.gains);
  const losses = formatSigned(totals.losses);
  return `Gains ${gains} · Losses ${losses}`;
}

export function MetricExplainer({
  title,
  note,
  value,
  previous,
  unit,
  reference,
  drivers,
  explanation,
  onExplain,
  spotlightId = null,
  isExplainPressed = false,
  className,
}: MetricExplainerProps) {
  const [previewId, setPreviewId] = useState<string | null>(null);
  const [pinnedId, setPinnedId] = useState<string | null>(null);
  const [hasAsked, setHasAsked] = useState(false);
  const difference = value - previous;
  const percent = percentChangeOf(value, previous);
  const change = changeWordsOf(percent, reference);
  const trend = trendOf(difference);
  const TrendIcon = TREND_ICON[trend];
  const ranked = rankedOf(drivers);
  const reach = reachOf(drivers);
  const activeId = activeIdOf(previewId, pinnedId, spotlightId);
  const active = ranked.find((entry) => entry.driver.id === activeId);
  const figure = formatCount(value);
  const spokenReading = spokenStreamOf(explanation);
  const summary = `${figure} ${unit}, ${change}, with ${drivers.length} drivers ranked by how much each one counted.`;

  const rows: DataRow[] = ranked.map((entry) => ({
    id: entry.driver.id,
    label: entry.driver.name,
    cells: [formatSigned(entry.driver.contribution), formatShare(entry.share)],
  }));

  /** A reading is said aloud once a person has asked for one: a demonstration stays silent. */
  function explainByHand() {
    setHasAsked(true);
    onExplain();
  }

  function togglePin(id: string) {
    setPinnedId((current) => {
      if (current === id) {
        return null;
      }
      return id;
    });
  }

  return (
    <ChartCard
      title={title}
      note={note}
      summary={summary}
      className={className}
    >
      <div className='flex flex-col gap-1'>
        <p className='flex flex-wrap items-baseline gap-x-2'>
          <MotionNumber
            value={value}
            format={COUNT_FORMAT}
            className='text-[28px] leading-9 font-semibold'
          />
          <span className='text-muted-foreground text-[13px]'>{unit}</span>
        </p>
        <p className='text-muted-foreground flex items-center gap-1.5 text-xs'>
          <TrendIcon className='size-3.5 shrink-0' />
          <span>
            {change}{' '}
            <span className='tabular-nums'>({formatSigned(difference)})</span>
          </span>
        </p>
      </div>
      <WhyItMoved
        explanation={explanation}
        onExplain={explainByHand}
        isExplainPressed={isExplainPressed}
      />
      <div className='flex flex-col gap-1.5'>
        <TotalBar ranked={ranked} activeId={activeId} />
        <p className='text-muted-foreground min-h-8 text-xs text-pretty tabular-nums @sm:min-h-0'>
          {captionOf(active, drivers, unit)}
        </p>
      </div>
      <div className='flex flex-col gap-1'>
        <h4 className='text-xs font-medium'>What moved it</h4>
        <ul className='-mx-2 flex flex-col'>
          {ranked.map((entry) => (
            <li key={entry.driver.id}>
              <DriverRow
                ranked={entry}
                reach={reach}
                isPinned={pinnedId === entry.driver.id}
                isLit={activeId === entry.driver.id}
                onPreview={setPreviewId}
                onTogglePin={togglePin}
              />
            </li>
          ))}
        </ul>
      </div>
      <LiveRegion message={spokenUnless(!hasAsked, spokenReading)} />
      <DataTable
        caption={`What moved ${title}`}
        columns={['Driver', `Contribution in ${unit}`, 'Share of what moved']}
        rows={rows}
      />
    </ChartCard>
  );
}

const DRIVERS: MetricDriver[] = [
  { id: 'signups', name: 'New signups', contribution: 48 },
  { id: 'returning', name: 'Returning teams', contribution: 39 },
  { id: 'mobile', name: 'Mobile release', contribution: 21 },
  { id: 'season', name: 'Seasonal dip', contribution: -18 },
  { id: 'trials', name: 'Trials that ended', contribution: -15 },
];

const DRIVER_IDS = DRIVERS.map((driver) => driver.id);

const CONTRIBUTIONS = DRIVERS.map((driver) => driver.contribution);

const ACTIVE_TEAMS = 1284;

const TEAMS_LAST_WEEK = ACTIVE_TEAMS - sumOf(CONTRIBUTIONS);

const READINGS = [
  'Most of the lift came from new signups after the launch on Tuesday, and from teams that came back once the mobile release fixed sign-in. A seasonal dip and a handful of trials that ended held the week back by 33 teams.',
  'New signups and returning teams added 87 active teams between them, and the mobile release brought 21 more. Without the seasonal dip and the trials that ended, the week would have closed 33 teams higher.',
];

const FIRST_READING = arrivedStreamOf(READINGS[0]);

const THINK_MS = 900;

const WORD_MS = 55;

const SECOND_READING_WORDS = wordsOf(READINGS[1]);

const WRITING_MS = SECOND_READING_WORDS.length * WORD_MS;

/** The round waits for the last word of the second reading, then leaves it time to be read. */
const READ_AFTER_MS = THINK_MS + WRITING_MS + 2000;

type PressKey = 'explain';

export default function Chart07() {
  const [turn, setTurn] = useState(0);
  const [spotlight, setSpotlight] = useState<string | null>(null);
  const { stream, start, show } = useWordStream(FIRST_READING);
  const { pressed, press } = usePress<PressKey>();

  function explain() {
    const following = turn + 1;
    const next = following % READINGS.length;
    setTurn(next);
    start(READINGS[next], { thinkMs: THINK_MS, wordMs: WORD_MS });
  }

  function resetDemo() {
    setTurn(0);
    setSpotlight(null);
    show(FIRST_READING);
  }

  const steps: AutoplayStep[] = [
    ...walkSteps(DRIVER_IDS, setSpotlight, { startAfter: 1300, stepMs: 750 }),
    { after: 900, run: () => setSpotlight(null) },
    { after: 600, run: () => press('explain') },
    { after: PRESS_LEAD_MS, run: explain },
    { after: READ_AFTER_MS, run: hold },
  ];
  const { ref, isAutoplaying, stopOnKeyboardFocus } = useChartDemo(steps, {
    loopAfter: 1600,
    onReset: resetDemo,
  });

  return (
    <div
      ref={ref}
      onFocus={stopOnKeyboardFocus}
      className='flex min-h-[32.5rem] w-full max-w-[30rem]'
    >
      <MetricExplainer
        title='Weekly active teams'
        note='Illustrative'
        value={ACTIVE_TEAMS}
        previous={TEAMS_LAST_WEEK}
        unit='teams'
        reference='last week'
        drivers={DRIVERS}
        explanation={stream}
        onExplain={explain}
        spotlightId={whileDemonstrating(isAutoplaying, spotlight)}
        isExplainPressed={pressed === 'explain'}
        className='w-full'
      />
    </div>
  );
}

import { useId } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';

type ChartCardProps = {
  title: string;
  /** A short mark beside the title, such as "Illustrative" over sample data. */
  note?: string;
  /** One line that says what the chart shows, read by screen readers with the title. */
  summary: string;
  /** Controls that change what the chart draws: a period, a view. */
  actions?: React.ReactNode;
  className?: string;
  children: React.ReactNode;
};

/**
 * The surface every chart sits on. It is a query container, so a chart lays itself out by the
 * room it has, and it is positioned, so the hidden table of a chart never widens the page.
 */
export function ChartCard({
  title,
  note,
  summary,
  actions,
  className,
  children,
}: ChartCardProps) {
  const titleId = useId();
  const summaryId = useId();

  return (
    <section
      aria-labelledby={titleId}
      aria-describedby={summaryId}
      className={cn(
        'bg-card hairline-ring ring-border @container relative flex flex-col gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
        className
      )}
    >
      <header className='flex min-h-7 flex-wrap items-center justify-between gap-x-3 gap-y-2'>
        <div className='flex min-w-0 items-center gap-2'>
          <h3 id={titleId} className='text-sm font-medium text-balance'>
            {title}
          </h3>
          {note && <Badge variant='secondary'>{note}</Badge>}
        </div>
        {actions}
      </header>
      {children}
      <p id={summaryId} className='sr-only'>
        {summary}
      </p>
    </section>
  );
}

export type DataRow = {
  id: string;
  /** The heading of the row: a day, a category, a step. */
  label: string;
  cells: readonly string[];
};

type DataTableProps = {
  caption: string;
  /** The heading of the label column first, then one per cell. */
  columns: readonly string[];
  rows: readonly DataRow[];
};

/**
 * The numbers a chart draws, as a table for screen readers. It is taken out of the flow, so the
 * piece it sits in has to be positioned: a hidden box inside an area that scrolls sideways widens
 * the page otherwise.
 */
export function DataTable({ caption, columns, rows }: DataTableProps) {
  return (
    <table className='sr-only'>
      <caption>{caption}</caption>
      <thead>
        <tr>
          {columns.map((column) => (
            <th key={column} scope='col'>
              {column}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={row.id}>
            <th scope='row'>{row.label}</th>
            {row.cells.map((cell, index) => (
              <td key={index}>{cell}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

import type { AutoplayStep } from '@/registry/ndeko/hooks/use-autoplay';
import { keyDelayOf } from '@/registry/ndeko/lib/demonstration';

type WalkOptions = {
  /** Milliseconds before the first position. */
  startAfter?: number;
  /** Milliseconds between two positions. */
  stepMs?: number;
};

/** One step per position, so a reading crosses a plot the way a pointer does. */
export function walkSteps<Position>(
  positions: readonly Position[],
  moveTo: (position: Position) => void,
  { startAfter = 700, stepMs = 240 }: WalkOptions = {}
): AutoplayStep[] {
  return positions.map((position, index) => {
    const after = keyDelayOf(index, startAfter, stepMs);
    return { after, run: () => moveTo(position) };
  });
}

/** What a demonstration points at lets go the moment a person takes over. */
export function whileDemonstrating<Value>(
  isDemonstrating: boolean,
  value: Value | null
) {
  if (isDemonstrating) {
    return value;
  }
  return null;
}

const LOCALE = 'en-US';

export const COUNT_FORMAT: Intl.NumberFormatOptions = {
  maximumFractionDigits: 0,
};

export const SIGNED_FORMAT: Intl.NumberFormatOptions = {
  maximumFractionDigits: 0,
  signDisplay: 'exceptZero',
};

export const USD_COMPACT_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  notation: 'compact',
  maximumFractionDigits: 1,
};

const COMPACT_FORMAT: Intl.NumberFormatOptions = {
  notation: 'compact',
  maximumFractionDigits: 1,
};

const COUNT = new Intl.NumberFormat(LOCALE, COUNT_FORMAT);

const SIGNED = new Intl.NumberFormat(LOCALE, SIGNED_FORMAT);

const COMPACT = new Intl.NumberFormat(LOCALE, COMPACT_FORMAT);

const USD_COMPACT = new Intl.NumberFormat(LOCALE, USD_COMPACT_FORMAT);

const DAY = new Intl.DateTimeFormat(LOCALE, {
  month: 'short',
  day: 'numeric',
  timeZone: 'UTC',
});

const MS_PER_DAY = 86_400_000;

export function formatCount(value: number) {
  return COUNT.format(value);
}

export function formatSigned(value: number) {
  return SIGNED.format(value);
}

export function formatCompact(value: number) {
  return COMPACT.format(value);
}

export function formatUsd(value: number) {
  return USD_COMPACT.format(value);
}

export function formatShare(share: number) {
  const percent = Math.round(share * 100);
  return `${percent}%`;
}

/** A start at zero has no percentage to grow from: it reads as no change. */
export function percentChangeOf(current: number, previous: number) {
  if (previous === 0) {
    return 0;
  }
  const difference = current - previous;
  const ratio = difference / Math.abs(previous);
  return Math.round(ratio * 100);
}

export function changeWordsOf(percent: number, reference: string) {
  if (percent === 0) {
    return `level with ${reference}`;
  }
  const size = Math.abs(percent);
  if (percent > 0) {
    return `up ${size}% on ${reference}`;
  }
  return `down ${size}% on ${reference}`;
}

export function nounOf(count: number, singular: string, plural: string) {
  if (count === 1) {
    return singular;
  }
  return plural;
}

/**
 * One label per day, or per `everyDays` days for a weekly series. Days are counted in UTC so the
 * server and the browser write the same label.
 */
export function dayLabelsOf(firstDay: string, count: number, everyDays = 1) {
  const start = Date.parse(`${firstDay}T00:00:00Z`);
  const stride = everyDays * MS_PER_DAY;
  return Array.from({ length: count }, (_, index) => {
    const elapsed = index * stride;
    return DAY.format(start + elapsed);
  });
}

export type Domain = {
  min: number;
  max: number;
};

export type Scale = Domain & {
  step: number;
  ticks: number[];
};

const NICE_FACTORS = [1, 2, 5, 10];

const EMPTY_DOMAIN: Domain = { min: 0, max: 0 };

export function clamp(value: number, min: number, max: number) {
  const atLeastMin = Math.max(value, min);
  return Math.min(atLeastMin, max);
}

export function lerp(from: number, to: number, amount: number) {
  const span = to - from;
  return from + span * amount;
}

export function sumOf(values: readonly number[]) {
  let total = 0;
  for (const value of values) {
    total += value;
  }
  return total;
}

export function extentOf(values: readonly number[]): Domain {
  if (values.length === 0) {
    return EMPTY_DOMAIN;
  }
  let min = values[0];
  let max = values[0];
  for (const value of values) {
    min = Math.min(min, value);
    max = Math.max(max, value);
  }
  return { min, max };
}

/** Bars and areas are read from zero, so their domain always holds it. */
export function withZero(domain: Domain): Domain {
  const min = Math.min(domain.min, 0);
  const max = Math.max(domain.max, 0);
  return { min, max };
}

/** Where a value sits in a domain, from 0 at its lowest to 1 at its highest. */
export function ratioOf(value: number, domain: Domain) {
  const span = domain.max - domain.min;
  if (span === 0) {
    return 0;
  }
  const offset = value - domain.min;
  return offset / span;
}

/** A flat series still needs room above and below it to be drawn. */
function spanOf(domain: Domain) {
  const span = domain.max - domain.min;
  if (span > 0) {
    return span;
  }
  const size = Math.abs(domain.max);
  return Math.max(size, 1);
}

function niceStepOf(roughStep: number) {
  const logarithm = Math.log10(roughStep);
  const exponent = Math.floor(logarithm);
  const magnitude = 10 ** exponent;
  const factor = NICE_FACTORS.find((candidate) => {
    const candidateStep = candidate * magnitude;
    return candidateStep >= roughStep;
  });
  const safeFactor = factor ?? 10;
  return safeFactor * magnitude;
}

function decimalsOf(step: number) {
  const logarithm = Math.log10(step);
  const exponent = Math.floor(logarithm);
  return Math.max(0, -exponent);
}

/** Adding zero turns a negative zero into zero, which a number format would write as -0. */
function roundedTo(value: number, decimals: number) {
  const factor = 10 ** decimals;
  const scaled = Math.round(value * factor);
  const rounded = scaled / factor;
  return rounded + 0;
}

/** A scale with round ticks that holds the whole domain, in at most `maxLines` steps. */
export function niceScaleOf(domain: Domain, maxLines: number): Scale {
  const span = spanOf(domain);
  const roughStep = span / maxLines;
  const step = niceStepOf(roughStep);
  const decimals = decimalsOf(step);
  const stepsBelow = Math.floor(domain.min / step);
  const lowest = stepsBelow * step;
  const highestWanted = Math.max(domain.max, lowest + step);
  const stepsAbove = Math.ceil(highestWanted / step);
  const lineCount = stepsAbove - stepsBelow;
  const tickCount = lineCount + 1;
  const ticks = Array.from({ length: tickCount }, (_, index) => {
    const tick = lowest + index * step;
    return roundedTo(tick, decimals);
  });
  const lastIndex = ticks.length - 1;
  return { min: ticks[0], max: ticks[lastIndex], step, ticks };
}

/** Columns share the plot equally and a mark sits in the middle of its column. */
export function columnCenterOf(index: number, count: number) {
  const center = index + 0.5;
  return center / count;
}

export function columnIndexAt(ratio: number, count: number) {
  const rawIndex = Math.floor(ratio * count);
  const lastIndex = Math.max(count - 1, 0);
  return clamp(rawIndex, 0, lastIndex);
}

export function percentOf(share: number) {
  const percent = share * 100;
  return `${percent}%`;
}

/** The whole numbers that lead from one position to another: the start is left out, the end is kept. */
export function positionsTo(from: number, to: number) {
  const gap = to - from;
  const distance = Math.abs(gap);
  const direction = Math.sign(gap);
  return Array.from({ length: distance }, (_, index) => {
    const travelled = index + 1;
    const offset = travelled * direction;
    return from + offset;
  });
}

type StreamedWordsProps = {
  words: readonly string[];
  /** How many of the words have arrived. */
  shown: number;
  /** Draws a caret after the last word while more are coming. */
  isStreaming?: boolean;
  className?: string;
};

/** Each word fades in as it mounts, so a streamed line settles word by word with no script per frame. */
export function StreamedWords({
  words,
  shown,
  isStreaming = false,
  className,
}: StreamedWordsProps) {
  const visible = words.slice(0, shown);

  return (
    <span className={className}>
      {visible.map((word, index) => (
        <span
          key={index}
          className='transition-opacity duration-300 ease-(--ease-out-strong) starting:opacity-0'
        >
          {word}{' '}
        </span>
      ))}
      {isStreaming && (
        <span
          aria-hidden='true'
          className='bg-foreground/50 inline-block h-[1em] w-[2px] animate-pulse rounded-full align-[-0.15em]'
        />
      )}
    </span>
  );
}

'use client';

import {
  useAutoplay,
  type AutoplayOptions,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';

/**
 * What every chart demo shares: the demonstration, the box that keeps its tallest height so a round
 * never moves the page, and a stop when the keyboard brings focus in. A person who tabs to a plot
 * reads it with the arrow keys from there, and has pressed no key inside the piece yet.
 */
export function useChartDemo(
  steps: readonly AutoplayStep[],
  options?: AutoplayOptions
) {
  const demo = useAutoplay(steps, options);
  const { ref, takeOver } = demo;

  useKeptHeight(ref);

  function stopOnKeyboardFocus(event: React.FocusEvent<HTMLElement>) {
    const isKeyboardFocus = event.target.matches(':focus-visible');
    if (isKeyboardFocus) {
      takeOver();
    }
  }

  return { ...demo, stopOnKeyboardFocus };
}

'use client';

import { useState } from 'react';

import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';

export type StreamStatus = 'idle' | 'thinking' | 'streaming' | 'done';

export type WordStream = {
  status: StreamStatus;
  words: readonly string[];
  /** How many of the words have arrived. */
  shown: number;
};

type StreamTiming = {
  /** Milliseconds before the first word. */
  thinkMs?: number;
  /** Milliseconds between two words. */
  wordMs?: number;
};

const IDLE: WordStream = { status: 'idle', words: [], shown: 0 };

export function wordsOf(text: string) {
  const trimmed = text.trim();
  if (trimmed === '') {
    return [];
  }
  return trimmed.split(/\s+/);
}

/** A text that is already there, with nothing left to arrive. */
export function arrivedStreamOf(text: string): WordStream {
  const words = wordsOf(text);
  return { status: 'done', words, shown: words.length };
}

export function textOf(stream: WordStream) {
  return stream.words.join(' ');
}

/** What a screen reader hears: the whole text once it has arrived, never each word on its way. */
export function spokenStreamOf(stream: WordStream) {
  if (stream.status === 'done') {
    return textOf(stream);
  }
  return '';
}

function withShown(shown: number) {
  return function reveal(current: WordStream): WordStream {
    return { ...current, shown };
  };
}

function withStatus(status: StreamStatus) {
  return function advance(current: WordStream): WordStream {
    return { ...current, status };
  };
}

/**
 * A text that arrives the way a model writes it: a moment of thought, then word after word. A real
 * product replaces it with its own stream and keeps the same `WordStream` shape.
 */
export function useWordStream(initial: WordStream = IDLE) {
  const [stream, setStream] = useState(initial);
  const { schedule, clearAll } = useTimeouts();

  function start(
    text: string,
    { thinkMs = 900, wordMs = 55 }: StreamTiming = {}
  ) {
    clearAll();
    const words = wordsOf(text);
    setStream({ status: 'thinking', words, shown: 0 });
    schedule(() => setStream(withStatus('streaming')), thinkMs);
    for (let shown = 1; shown <= words.length; shown += 1) {
      const elapsed = shown * wordMs;
      schedule(() => setStream(withShown(shown)), thinkMs + elapsed);
    }
    const streamMs = words.length * wordMs;
    const lastWordAt = thinkMs + streamMs;
    const settleMs = wordMs * 2;
    schedule(() => setStream(withStatus('done')), lastWordAt + settleMs);
  }

  function show(next: WordStream) {
    clearAll();
    setStream(next);
  }

  return { stream, start, show };
}
